# qx2_hamming :: ('karolin', 'kathrin')
def qx2_hamming(a, b):
    if len(a) != len(b):
        return -1
    return sum(1 for x, y in zip(a, b) if x != y)

if __name__ == '__main__':
    print(qx2_hamming(('karolin', 'kathrin')))

